 return <g>
 {[0,1,2,3,4].map(i=><g key={i} opacity=".28" transform={`translate(${100+i*218} ${520+Math.sin(s+i)*12})`}><ellipse rx="70" ry="92" fill={i%2?'#dda36f':'#db8f9e'}/><path d="M0 92q-20 100 0 210" fill="none" stroke="#dfb7a0" strokeWidth="2"/></g>)}
 <path d="M0 540Q540 710 1080 540" stroke="#cdb398" fill="none" strokeWidth="5"/>
