 </g>;
};

const Grid:React.FC=()=>{const {s}=useS();const n=43*between(s,en('cuarenta'),en('tres'));const pull=between(s,B[2],B[3]);
 return <g transform={`translate(540 985) scale(${1.12-pull*.12}) translate(-540 -985)`}>
 {Array.from({length:100},(_,i)=>{const chosen=i<Math.floor(n);return <Wallet key={i} x={130+(i%10)*90} y={580+Math.floor(i/10)*101} scale={.096} card={chosen} open={chosen?1:0} dust={1}/>;})}
 <g transform={`translate(540 ${1630-(s-B[2])*3})`}><rect x="-210" y="-54" width="420" height="108" rx="29" fill="#242b36" stroke="#797c81" strokeWidth="2"/><text y="17" textAnchor="middle" fontSize="43" fill="#e5d6b9">Bankrate 2024</text></g>
 {s>=en('cuarenta')&&<text x="540" y="470" textAnchor="middle" fill={G} fontWeight="800" fontSize="78">{Math.floor(n)} / 100</text>}
 </g>;
};

const Mountain:React.FC=()=>{const {s}=useS();const fly=between(s,en('total'),en('veintisiete'));const rise=between(s,en('veintisiete'),B[4]);return <g>
 <Wallet y={1120} scale={.8-fly*.34} dust={1}/>
 {Array.from({length:43},(_,i)=>{const p=clamp01(fly*2-(i%11)*.09);const row=Math.floor(i/8);return <Gift key={i} x={540+(i%8-3.5)*(65+row*6)*p} y={1090+row*58-p*(240+(i%4)*40)-rise*100} scale={.15*p} dust={1} angle={(i%5-2)*13}/>;})}
 </g>;};

const Store:React.FC=()=>{const {s}=useS();const opening=between(s,en('quién'),en('dinero',1));const purchased=between(s,en('cobró'),en('compró'));const denied=between(s,en('nunca'),en('nada'));return <g>
 <Vault open={opening}/>
 <path d="M120 1490H950M250 1530v300M800 1530v300" stroke="#667080" strokeWidth="13" opacity=".4"/>
 <Gift x={280-denied*45} y={1460} scale={.48} dust={denied}/>
 {Array.from({length:9},(_,i)=>{const p=clamp01(purchased*2-i*.095);return <Coin key={i} x={230+p*500} y={1470-p*540-Math.sin(p*Math.PI)*100+i%3*32} r={24} />;})}
 <g opacity={denied}><path d="M450 1450H800" stroke="#8c96a1" strokeWidth="8" strokeDasharray="20 16"/><circle cx="540" cy="1460" r="48" fill="#6b747c"/><path d="M518 1438l44 44m0-44-44 44" stroke="#cbd1d5" strokeWidth="8"/></g>
 </g>;};

