 <path d="M115 710Q300 645 535 712Q780 645 969 710L920 1400Q727 1336 535 1410Q337 1335 159 1400Z" fill="#7c5147"/>
 <path d="M110 675Q320 603 535 680Q755 603 975 675L925 1360Q730 1293 535 1370Q340 1293 155 1360Z" fill="url(#paper)" stroke="#f8e8c9" strokeWidth="8"/>
 <path d="M535 680V1370" stroke="#ad927b" strokeWidth="9"/>
 {[0,1,2,3,4,5,6].map(i=><path key={i} d={`M190 ${840+i*66}Q350 ${818+i*66} 490 ${850+i*66}M580 ${850+i*66}Q740 ${818+i*66} 902 ${840+i*66}`} fill="none" stroke="#9b8d80" strokeWidth="2" opacity=".55"/>)}
