 <g transform={`translate(${340+Math.sin((s-B[5])*2)*70} ${1000+(s-B[5])*23}) rotate(32)`}><path d="M0 0L22-260L48-277L45-7L20 35Z" fill="url(#gold)"/><path d="M0 0L20 35L45-7" fill="#303037"/></g>
 <Gift x={285} y={1220} scale={.27} dust={1}/>
