const Use:React.FC=()=>{const {s}=useS();const lift=between(s,en('busca'),en('cartera',2));const blow=between(s,en('cartera',2),en('correos'));const email=between(s,en('correos'),en('apps'));const pay=between(s,en('Úsala'),en('comprar'));return <g>
