 </g>;};

const Scene:React.FC<{i:number}>=({i})=>{const {s}=useS();const dust=i===7?0:1;const push=between(s,B[i],B[i+1]);const color=tono(s,[B[0],B[1],B[2],en('veintisiete'),B[4],B[6],B[7]],['#55423d','#79515d','#3b4147','#522d32','#253044','#75603c','#55423d']);
 return <AbsoluteFill>
 <Textura tipo={i===1||i===5?'papel':'piel'} base={`radial-gradient(ellipse at 42% 42%, ${color}, #15131a)`} linea={i===1?'#cb9c8e':'#8a7263'} luz="rgba(255,220,180,.12)" semilla={i+3}/>
 <Brillo x={500} y={940} r={480} color={i===6?'rgba(255,200,61,.23)':'rgba(246,184,162,.15)'}/>
 <svg viewBox="0 0 1080 1920" width="1080" height="1920" style={{position:'absolute',inset:0,fontFamily:FONT}}>
 <Defs/>
 <g transform={`translate(540 1030) scale(${1+push*.035}) translate(${-540+Math.sin(s*.32)*5} ${-1030-push*12})`}>
 {(i===0||i===7)&&<><Wallet y={1080} dust={dust}/>{i===0&&<g><path d="M550 895Q850 760 1140 710" stroke="url(#gold)" strokeWidth="10" fill="none" strokeDasharray="730" strokeDashoffset={730*(1-between(s,en('ganancia'),B[1]))}/>{Array.from({length:30},(_,n)=><circle key={n} cx={240+(n*89)%620} cy={770+((n*57+s*29)%460)} r={2+n%4} fill="#dfcfba" opacity=".5"/>)}</g>}</>}
 {i===1&&<Party/>}{i===2&&<Grid/>}{i===3&&<Mountain/>}
 {i===4&&<Entrar t={B[4]} x={540} y={970} dur={.65} zoom={4} fuera={<Vault open={0}/>} dentro={<Store/>}/>}
 {i===5&&<Ledger/>}{i===6&&<Use/>}
 </g></svg>
 {i===3&&<Contador hasta={s<en('veintisiete')?244:27000} t0={s<en('veintisiete')?en('doscientos'):en('veintisiete')} t1={s<en('veintisiete')?en('dólares'):en('dólares',2)} y={530} prefijo="$" sufijo={s<en('veintisiete')?'':' M'} size={100} color={s<en('veintisiete')?G:'#FF4D4D'}/>}
 <Profundidad semilla={5+i} manchas={3} color="rgba(18,13,15,.5)" lejos="rgba(255,221,178,.12)"/>
 <AbsoluteFill style={{background:'radial-gradient(ellipse at 48% 48%, transparent 40%, rgba(8,6,13,.5))'}}/>
 </AbsoluteFill>;
};

export const Escena:React.FC=()=>{const {s}=useS();let i=0;while(i<7&&s>=B[i+1])i++;
 if(i===0||i===1)return <Paso t={B[1]} tipo="alejar" antes={<Scene i={0}/>} despues={<Scene i={1}/>}/>;
 if(i===4)return <Scene i={4}/>;
 if(i===5||i===6)return <Paso t={B[6]} tipo="barrido" antes={<Scene i={5}/>} despues={<Scene i={6}/>}/>;
 return <Scene i={i}/>;
};

